// Index focus set: the only event pages that are indexable (robots "index" +
// sitemap). Everything else is noindex,follow. The list is generated by
// scripts/select-index-focus.mjs and committed to src/data/index-focus.json;
// see that script's header for the why. Browser-safe (no astro:content).
import focus from '../data/index-focus.json';
import type { Country, Sport } from './types';
import { seasonOf } from './types';

export const FOCUS_SLUGS: ReadonlySet<string> = new Set<string>(focus.slugs);
export const FOCUS_LIMIT: number = focus.limit;

export const isFocus = (slug: string): boolean => FOCUS_SLUGS.has(slug);

/** Landing pages need this many focus events to be indexable themselves. */
export const MIN_FOCUS_PER_LANDING = 3;

interface Keyed {
  slug: string;
  sport: Sport;
  country: Country;
  start: string | Date;
}

/** Number of focus events in a sport × country × season bucket. */
export function focusCount(events: Keyed[], sport: Sport, country: Country, year: number): number {
  let n = 0;
  for (const e of events) {
    if (e.sport === sport && e.country === country && seasonOf(e.start) === year && FOCUS_SLUGS.has(e.slug)) n++;
  }
  return n;
}
